#include <immer/vector.hpp>
#include <iostream>
#include <string>

int main(int argc, char* argv[]) {
    int n = (argc > 1) ? std::stoi(argv[1]) : 11;

    auto v = immer::vector<int>{};
    for (int i = 0; i < n; ++i) {
        v = v.push_back(i + 1);
    }

    auto sum = 0;
    for (auto x : v) {
        sum += x;
    }

    std::cout << sum << std::endl;

    auto v2 = immer::vector<int>{};
    for (int i = 0; i < v.size(); ++i) {
        v2 = v2.push_back(v[i] * 2);
    }

    sum = 0;
    for (auto x : v2) {
        sum += x;
    }

    std::cout << sum << std::endl;

    return 0;
}


