use std::io::{self, Write};

pub fn parse_n_arg<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut args = args.into_iter();
    let _program_name = args.next();

    match args.next() {
        Some(raw) => parse_stoi_i32(&raw),
        None => 11,
    }
}

fn parse_stoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'+') => {
            index += 1;
            false
        }
        Some(b'-') => {
            index += 1;
            true
        }
        _ => false,
    };

    let digits_start = index;
    let limit = if negative {
        -(i32::MIN as i64)
    } else {
        i32::MAX as i64
    };
    let mut magnitude = 0i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = (bytes[index] - b'0') as i64;
        if magnitude > (limit - digit) / 10 {
            abort_stoi("out_of_range");
        }
        magnitude = magnitude * 10 + digit;
        index += 1;
    }

    if index == digits_start {
        abort_stoi("invalid_argument");
    }

    if negative {
        -(magnitude as i64) as i32
    } else {
        magnitude as i32
    }
}

fn abort_stoi(kind: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of 'std::{}'",
        kind
    );
    let _ = writeln!(stderr, "  what():  stoi");
    let _ = stderr.flush();
    std::process::abort();
}

use std::ops::Index;
use std::slice;

#[derive(Clone, Debug, Default)]
pub struct Vector<T> {
    values: Vec<T>,
}

impl<T> Vector<T> {
    pub fn new() -> Self {
        Self { values: Vec::new() }
    }

    pub fn push_back(mut self, value: T) -> Self {
        self.values.push(value);
        self
    }

    pub fn len(&self) -> usize {
        self.values.len()
    }

    pub fn iter(&self) -> slice::Iter<'_, T> {
        self.values.iter()
    }
}

impl<T> Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &Self::Output {
        &self.values[index]
    }
}

use std::io::{self, Write};

use super::cli::parse_n_arg;
use super::vector::Vector;

pub fn run<I>(args: I)
where
    I: IntoIterator<Item = String>,
{
    let n = parse_n_arg(args);
    let (first_sum, second_sum) = compute_outputs(n);

    let mut stdout = io::stdout().lock();
    let _ = writeln!(stdout, "{}", first_sum);
    let _ = stdout.flush();
    let _ = writeln!(stdout, "{}", second_sum);
    let _ = stdout.flush();
}

fn compute_outputs(n: i32) -> (i32, i32) {
    let mut v = Vector::new();
    let mut i = 0i32;

    while i < n {
        v = v.push_back(i.wrapping_add(1));
        i = i.wrapping_add(1);
    }

    let mut sum = 0i32;
    for &x in v.iter() {
        sum = sum.wrapping_add(x);
    }
    let first_sum = sum;

    let mut v2 = Vector::new();
    let mut index = 0usize;
    while index < v.len() {
        v2 = v2.push_back(v[index].wrapping_mul(2));
        index += 1;
    }

    sum = 0;
    for &x in v2.iter() {
        sum = sum.wrapping_add(x);
    }

    (first_sum, sum)
}
